Навигация по Int требует назначения для Int. String.self не соответствует значениям ссылок; после исправления eventID используется для поиска зала.

import SwiftUI
struct EventScreen: View {
    let eventID = 84
    @State private var showsTicket = false
    var body: some View {
        VStack {
            Text("Событие \(eventID)")
            Toggle("Показать билет", isOn: $showsTicket)
        }
        .sheet(isPresented: $showsTicket) {
            Text("Билет на событие \(eventID)")
        }
    }
}

sheet использует $showsTicket и при закрытии обновляет этот флаг. Деталь остаётся той же: модальное представление не добавляет маршрут в стек.

import SwiftUI
struct EventsScreen: View {
    @State private var path: [Int] = []
    private let events = [86: "Открытая сцена"]
    var body: some View {
        NavigationStack(path: $path) {
            Button("Из уведомления") { path.append(86) }
                .navigationDestination(for: Int.self) { eventID in
                    VStack {
                        Text(events[eventID] ?? "Событие удалено")
                        Button("В начало") { path.removeAll() }
                    }
                }
        }
    }
}

Кнопка добавляет id в привязанный к NavigationStack массив. Назначение Int строит деталь; очистка пути возвращает к корню.
